import{_ as r,y as l,a as d,o as t,a6 as o,c as n,w as a,I as s,D as p,a7 as c}from"./chunks/framework.CJDy2q7X.js";const q=JSON.parse('{"title":"Upload Customizable File","description":"","frontmatter":{"outline":false,"examples":[{"id":"upload-then-add","title":"Upload a File, then Add to Cart","description":"A file-type customizable option needs a binary upload, which cannot travel over GraphQL. Upload the file over REST to get a token, then reference the token in the GraphQL add-to-cart mutation.","query":"# Step 2 — upload the file over REST (binary cannot travel over GraphQL):\\n#\\n#   POST /api/shop/customizable-option-files   (multipart/form-data)\\n#   product_id=2977  option_id=11  file=@spec.pdf\\n#   → { \\"token\\": \\"…\\", \\"fileName\\": \\"spec.pdf\\", \\"optionId\\": 11 }\\n#\\n# Step 3 — add to cart over GraphQL with the token:\\nmutation createAddProductInCart($input: createAddProductInCartInput!) {\\n  createAddProductInCart(input: $input) {\\n    addProductInCart {\\n      id\\n      grandTotal\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"productId\\": 2977,\\n    \\"quantity\\": 1,\\n    \\"customizableOptions\\": {\\n      \\"9\\": [9],\\n      \\"10\\": [12],\\n      \\"11\\": [\\"<token-from-upload-endpoint>\\"]\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAddProductInCart\\": {\\n      \\"addProductInCart\\": {\\n        \\"id\\": \\"6895\\",\\n        \\"grandTotal\\": 54,\\n        \\"success\\": true,\\n        \\"message\\": \\"Product added to cart successfully\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/upload-customizable-file.md","filePath":"api/graphql-api/shop/mutations/upload-customizable-file.md","lastUpdated":1786429091000}'),u={name:"api/graphql-api/shop/mutations/upload-customizable-file.md"};function h(m,e,f,g,_,b){const i=l("Mermaid");return t(),d("div",null,[e[1]||(e[1]=o('<h1 id="upload-customizable-file" tabindex="-1">Upload Customizable File <a class="header-anchor" href="#upload-customizable-file" aria-label="Permalink to &quot;Upload Customizable File&quot;">​</a></h1><p>A <code>file</code>-type customizable option (e.g. &quot;upload your design&quot;) needs a binary file. <strong>A file cannot travel over GraphQL</strong>, so the upload itself is a REST call — but the rest of the flow stays in GraphQL. You upload once over REST to get a <strong>token</strong>, then reference the token in the GraphQL <a href="/api/graphql-api/shop/mutations/add-to-cart.html">Add to Cart</a> mutation.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2>',3)),(t(),n(c,null,{default:a(()=>[p(i,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20read%5B%221.%20Read%20option%20id%22%5D%0A%20%20up%5B%222.%20Upload%20(REST)%22%5D%0A%20%20add%5B%223.%20Add%20to%20cart%22%5D%0A%20%20cart%5B%22File%20in%20cart%22%5D%0A%20%20order%5B%22File%20to%20order%22%5D%0A%20%20read%20--%3E%20up%20--%3E%20add%20--%3E%20cart%20--%3E%20order%0A"})]),fallback:a(()=>e[0]||(e[0]=[s(" Loading... ",-1)])),_:1})),e[2]||(e[2]=o('<ol><li><strong>Read the option</strong> from the product&#39;s <code>customizableOptions</code> (<a href="/api/graphql-api/shop/queries/get-product.html">Single Product</a>) — a <code>file</code>-type option carries its <code>_id</code> and the allowed extensions.</li><li><strong>Upload the file over REST</strong> — <code>POST /api/shop/customizable-option-files</code> (multipart) with <code>product_id</code>, <code>option_id</code>, <code>file</code>. It returns a short-lived <code>token</code>. This is REST-only; see the <a href="/api/rest-api/shop/cart/upload-customizable-file.html">REST upload endpoint</a> for the full request/response.</li><li><strong>Add to cart over GraphQL</strong> — pass the token as that option&#39;s value: <code>customizableOptions: { &quot;11&quot;: [&quot;&lt;token&gt;&quot;] }</code>. The mutation carries only the token string.</li><li><strong>Core owns the rest</strong> — the file is stored with the cart, then moved to the order automatically at place-order.</li></ol><h2 id="which-file-formats-are-allowed" tabindex="-1">Which file formats are allowed? <a class="header-anchor" href="#which-file-formats-are-allowed" aria-label="Permalink to &quot;Which file formats are allowed?&quot;">​</a></h2><p>There is no fixed API list — the <strong>admin sets the allowed extensions per option</strong> (the option&#39;s &quot;Supported File Extensions&quot;, e.g. <code>pdf</code> or <code>jpg,png,pdf</code>). Read them from the product&#39;s <code>customizableOptions</code>; a mismatched extension is rejected at upload.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/mutations/add-to-cart.html">Add to Cart</a> — reference the token here</li><li><a href="/api/graphql-api/shop/queries/get-product.html">Single Product</a> — read the customizable options</li><li><a href="/api/rest-api/shop/cart/upload-customizable-file.html">REST upload endpoint</a> — the actual multipart upload</li></ul>',5))])}const A=r(u,[["render",h]]);export{q as __pageData,A as default};
